export function createRecovery({state,pageTitle,esc,navigate,save,render}){
 let mode='id',method='phone',stage='verify',sent='',verified=false;
 const input=(name,label,type='text')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" required><span class="field-error"></span></label>`;
 function page(){return `<div class="account-contained recovery-page">${pageTitle('아이디 · 비밀번호 찾기','','login')}<section class="content-card"><div class="recovery-tabs">${[['id','아이디 찾기'],['password','비밀번호 재설정']].map(([k,t])=>`<button type="button" data-recovery-mode="${k}" aria-pressed="${mode===k}">${t}</button>`).join('')}</div>${stage==='done'?`<div class="recovery-result"><h2>${mode==='id'?'가입한 아이디를 확인했어요':'비밀번호를 변경했어요'}</h2>${mode==='id'?`<strong>${esc(state.profile.username||state.profile.email)}</strong>`:''}<button class="btn primary" data-nav="login">로그인으로</button></div>`:`<form id="recovery-form">${verified?`${input('password','새 비밀번호','password')}${input('confirm','새 비밀번호 확인','password')}`:`<p class="prose">가입 시 등록한 연락처로 인증해 주세요.</p><div class="recovery-methods">${[['phone','휴대전화 인증'],['email','이메일 인증']].map(([k,t])=>`<label><input type="radio" name="method" value="${k}" ${method===k?'checked':''}>${t}</label>`).join('')}</div>${mode==='password'?input('username','이메일 또는 아이디'):''}<div class="recovery-send">${input('contact',method==='phone'?'휴대전화 번호':'이메일',method==='phone'?'tel':'email')}<button type="button" class="btn secondary" data-recovery-send>인증번호 받기</button></div>${input('code','인증번호')}`}<p class="recovery-error" role="alert"></p><p class="record-note">체험 인증입니다. 문자·이메일은 발송되지 않으며 인증번호는 123456입니다.</p><button class="btn primary" type="submit">${verified?'비밀번호 변경':'인증하고 계속하기'}</button></form>`}</section></div>`;}
 function bind(root){const f=root.querySelector('#recovery-form');root.querySelectorAll('[data-recovery-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.recoveryMode;stage='verify';sent='';verified=false;render();});if(!f)return;const err=t=>f.querySelector('.recovery-error').textContent=t;const norm=v=>method==='phone'?v.replace(/\D/g,''):v.trim().toLowerCase();f.querySelectorAll('[name=method]').forEach(b=>b.onchange=()=>{method=b.value;sent='';render();});const send=f.querySelector('[data-recovery-send]');if(send)send.onclick=()=>{const el=f.elements.contact;if(!el.reportValidity())return;sent=norm(el.value);err('체험 인증번호 123456을 입력해 주세요.');};f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity())return;if(verified){if(f.elements.password.value.length<8)return err('비밀번호를 8자 이상 입력해 주세요.');if(f.elements.password.value!==f.elements.confirm.value)return err('비밀번호가 일치하지 않아요.');const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(f.elements.password.value));state.authPasswordHash=Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');save();verified=false;stage='done';render();return;}if(!sent||sent!==norm(f.elements.contact.value)||f.elements.code.value!=='123456')return err('연락처와 인증번호를 확인하고 다시 인증해 주세요.');if(!state.registered||!state.profile[method]||norm(state.profile[method])!==sent)return err('입력한 정보와 일치하는 가입 정보를 찾을 수 없어요.');if(mode==='password'&&![state.profile.username,state.profile.email].filter(Boolean).some(v=>v.toLowerCase()===f.elements.username.value.trim().toLowerCase()))return err('아이디와 연락처를 확인해 주세요.');if(mode==='id')stage='done';else verified=true;sent='';render();};}
 return {page,bind};
}
